const canvas=document.querySelector('#board'),ctx=canvas.getContext('2d');
import {W,H,MAX_PULL,TYPES,advance} from './physics.js';
import {planShot} from './ai.js';
let pieces=[],turn=0,moving=false,drag=null,gameOver=false,aiTimer=null,lastTime=0,accumulator=0,soundOn=false,audio=null,shotCount=0;
const $=s=>document.querySelector(s),status=t=>$('#status').textContent=t;
Object.values(TYPES).forEach(t=>$('#weights').insertAdjacentHTML('beforeend',`<div class="weight-item"><i>${t.label[0]}</i>${t.name}<br>${t.mass.toFixed(2)}</div>`));
function point(col,row){return{x:40+col*67.5,y:40+row*(600/9)}}
function reset(){clearTimeout(aiTimer);pieces=[];for(let team=0;team<2;team++){const back=team===0?9:0;['rook','horse','elephant','guard',null,'guard','elephant','horse','rook'].forEach((type,col)=>{if(type)add(type,team,col,back)});add('king',team,4,team===0?8:1);[1,7].forEach(c=>add('cannon',team,c,team===0?7:2));[0,2,4,6,8].forEach(c=>add('pawn',team,c,team===0?6:3))}turn=0;moving=false;drag=null;gameOver=false;shotCount=0;accumulator=0;$('#result').hidden=true;status('당신의 차례입니다');$('#power').textContent='파란 말을 뒤로 당겨보세요';updateCounts()}
function add(type,team,col,row){pieces.push({id:pieces.length,type,team,...point(col,row),vx:0,vy:0,r:TYPES[type].radius,alive:true})}
function updateCounts(){let counts=[0,0];pieces.forEach(p=>{if(p.alive)counts[p.team]++});$('#blueCount').textContent=counts[0];$('#redCount').textContent=counts[1];return counts}
function beep(f=220){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.12)}catch{}}
// Equal launch speed at equal pull; momentum grows with mass. No team-specific physics.
function shoot(p,dx,dy){const len=Math.hypot(dx,dy);if(len<8)return false;const speed=Math.min(MAX_PULL,len)*7;p.vx=dx/len*speed;p.vy=dy/len*speed;moving=true;shotCount++;drag=null;status(turn===0?'당신의 한 수!':'AI의 한 수!');$('#power').textContent='말이 멈추면 다음 차례';beep(320);return true}
function step(dt){const active=advance(pieces,dt,event=>{if(event==='out')beep(130);else if(Math.random()<.2)beep(180)});if(moving&&!active)finishTurn()}
function finishTurn(){moving=false;const counts=updateCounts();if(counts[0]===0||counts[1]===0){gameOver=true;$('#result').hidden=false;$('#resultTitle').textContent=counts[0]===0&&counts[1]===0?'무승부':counts[1]===0?'당신의 승리!':'AI의 승리';$('#resultText').textContent=`${shotCount}번의 한 수로 마무리된 승부. 다시 도전해 보세요.`;status('한 판이 끝났습니다');return}turn=1-turn;if(turn===1){status('AI가 다음 수를 고르는 중');aiTimer=setTimeout(aiMove,850)}else{status('당신의 차례입니다');$('#power').textContent='파란 말을 뒤로 당겨보세요'}}
async function aiMove(){
  if(gameOver||turn!==1)return;
  const original=pieces;
  const valid=()=>pieces===original&&!gameOver&&turn===1&&!moving;
  const best=await planShot(pieces,$('#difficulty').value,valid);
  if(!valid()||!best)return;
  const p=pieces.find(p=>p.id===best.id&&p.alive);
  if(p)shoot(p,Math.cos(best.angle)*best.pull,Math.sin(best.angle)*best.pull);
}
function coords(e){const b=canvas.getBoundingClientRect();return{x:(e.clientX-b.left)*W/b.width,y:(e.clientY-b.top)*H/b.height}}
canvas.addEventListener('pointerdown',e=>{if(turn!==0||moving||gameOver)return;const pos=coords(e),p=pieces.find(p=>p.alive&&p.team===0&&Math.hypot(pos.x-p.x,pos.y-p.y)<p.r+7);if(p){drag={p,pos,pointer:e.pointerId};canvas.setPointerCapture(e.pointerId);e.preventDefault()}});
canvas.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;drag.pos=coords(e);$('#power').textContent=`발사 세기 ${Math.round(Math.min(1,Math.hypot(drag.p.x-drag.pos.x,drag.p.y-drag.pos.y)/MAX_PULL)*100)}%`});
canvas.addEventListener('pointerup',e=>{if(!drag||drag.pointer!==e.pointerId)return;const {p}=drag,pos=coords(e);drag=null;shoot(p,p.x-pos.x,p.y-pos.y)});
canvas.addEventListener('pointercancel',()=>{drag=null;$('#power').textContent='파란 말을 뒤로 당겨보세요'});
$('#restart').onclick=reset;$('#again').onclick=reset;$('#sound').onclick=()=>{soundOn=!soundOn;$('#sound').textContent=soundOn?'소리 켜짐':'소리 꺼짐';$('#sound').setAttribute('aria-pressed',String(soundOn));beep(440)};
function resize(){const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);
function draw(){ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#e9c883');bg.addColorStop(.5,'#dfb86c');bg.addColorStop(1,'#d1a253');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#9c713321';ctx.lineWidth=1;for(let i=0;i<90;i++){ctx.beginPath();ctx.moveTo(0,i*8);ctx.bezierCurveTo(180,i*8-8,420,i*8+12,W,i*8+3);ctx.stroke()}ctx.strokeStyle='#503f29';ctx.lineWidth=1.5;for(let c=0;c<9;c++){const p=point(c,0);ctx.beginPath();ctx.moveTo(p.x,40);ctx.lineTo(p.x,640);ctx.stroke()}for(let r=0;r<10;r++){const p=point(0,r);ctx.beginPath();ctx.moveTo(40,p.y);ctx.lineTo(580,p.y);ctx.stroke()}for(const row of [0,7]){ctx.beginPath();ctx.moveTo(point(3,row).x,point(3,row).y);ctx.lineTo(point(5,row+2).x,point(5,row+2).y);ctx.moveTo(point(5,row).x,point(5,row).y);ctx.lineTo(point(3,row+2).x,point(3,row+2).y);ctx.stroke()}ctx.fillStyle='#705329';ctx.font='11px Georgia';ctx.textAlign='center';for(let c=0;c<9;c++)ctx.fillText(c+1,point(c,0).x,20);for(let r=0;r<10;r++)ctx.fillText(r+1,19,point(0,r).y+4);
for(const p of pieces){if(!p.alive)continue;const selected=drag?.p===p;ctx.save();ctx.translate(p.x,p.y);ctx.shadowColor='#4b2d2360';ctx.shadowBlur=5;ctx.shadowOffsetY=4;ctx.beginPath();for(let i=0;i<8;i++){const a=(i+.5)*Math.PI/4;ctx.lineTo(Math.cos(a)*p.r,Math.sin(a)*p.r)}ctx.closePath();ctx.fillStyle=selected?'#fff9d6':'#fffaf0';ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.strokeStyle=selected?'#386e58':'#cfb991';ctx.lineWidth=selected?3:1.5;ctx.stroke();ctx.beginPath();ctx.arc(0,0,p.r-5,0,Math.PI*2);ctx.strokeStyle=p.team===0?'#315ca943':'#b83a3243';ctx.lineWidth=.7;ctx.stroke();ctx.fillStyle=p.team===0?'#234fa0':'#b32c27';ctx.font=`bold ${Math.round(p.r*1.23)}px "Noto Serif KR",serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(TYPES[p.type].label[p.team],0,1);ctx.restore()}
if(drag){const p=drag.p,dx=p.x-drag.pos.x,dy=p.y-drag.pos.y,len=Math.hypot(dx,dy);if(len>0){const scale=Math.min(len,MAX_PULL)/len;ctx.strokeStyle='#183f34';ctx.lineWidth=3;ctx.setLineDash([6,5]);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+dx*scale,p.y+dy*scale);ctx.stroke();ctx.setLineDash([]);const a=Math.atan2(dy,dx),x=p.x+dx*scale,y=p.y+dy*scale;ctx.beginPath();ctx.moveTo(x-12*Math.cos(a-.5),y-12*Math.sin(a-.5));ctx.lineTo(x,y);ctx.lineTo(x-12*Math.cos(a+.5),y-12*Math.sin(a+.5));ctx.stroke();ctx.strokeStyle='#ffffff90';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(drag.pos.x,drag.pos.y);ctx.stroke()}}}
function frame(time){const elapsed=Math.min((time-lastTime)/1000,.05);lastTime=time;if(moving){accumulator+=elapsed;while(accumulator>=1/240){step(1/240);accumulator-=1/240;if(!moving){accumulator=0;break}}updateCounts()}draw();requestAnimationFrame(frame)}resize();reset();requestAnimationFrame(frame);
